css:
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@600&family=Rajdhani:wght@400;600&display=swap');
html, body { background-color: var(--neon-bg) !important; color: var(--neon-text) !important; font-family: 'Rajdhani', 'Segoe UI', sans-serif !important; }
a { color: var(--neon-primary) !important; }
a:focus, a:hover, a:active, a.active { color: var(--neon-pink) !important; }
.navbar { background-color: var(--neon-surface) !important; }
.panel { background: var(--neon-surface) !important; color: var(--neon-text) !important; border: 1px solid var(--neon-border) !important; border-radius: var(--neon-radius) !important; box-shadow: 0 0 12px rgba(0, 229, 255, 0.08) !important; transition: box-shadow 0.25s ease, transform 0.25s ease !important; }
.panels-container:not(.panels-canvas) .panel:hover { transform: translateY(-2px); box-shadow: 0 4px 18px rgba(0, 229, 255, 0.25) !important; }
.panel .navbar, .panel .navbar-section { background: linear-gradient(90deg, rgba(0, 229, 255, 0.18), transparent 70%), var(--neon-surface) !important; color: var(--neon-primary) !important; font-family: 'Orbitron', 'Rajdhani', sans-serif !important; letter-spacing: 0.05em !important; border-bottom: 1px solid var(--neon-border) !important; }
.btn-header { background: transparent !important; color: var(--neon-primary) !important; }
.btn { background: var(--neon-surface) !important; border-color: var(--neon-primary) !important; color: var(--neon-primary) !important; border-radius: var(--neon-radius) !important; transition: box-shadow 0.2s ease, background 0.2s ease !important; }
.btn:focus, .btn:hover { background: rgba(0, 229, 255, 0.12) !important; box-shadow: 0 0 8px rgba(0, 229, 255, 0.5) !important; color: var(--neon-primary) !important; }
.btn.btn-primary { background: var(--neon-primary) !important; border-color: var(--neon-primary-dark) !important; color: var(--neon-on-primary) !important; box-shadow: 0 0 10px rgba(0, 229, 255, 0.45) !important; }
.btn.btn-primary:focus, .btn.btn-primary:hover { background: var(--neon-primary-dark) !important; box-shadow: 0 0 16px rgba(0, 229, 255, 0.7) !important; color: var(--neon-on-primary) !important; }
.btn.btn-link { background: transparent !important; border-color: transparent !important; color: var(--neon-primary) !important; }
.btn.btn-error { background: var(--neon-pink) !important; border-color: var(--neon-pink) !important; color: #ffffff !important; }
.emergency-btn { color: var(--neon-pink) !important; background-color: var(--neon-surface) !important; border-color: var(--neon-pink) !important; }
.emergency-btn:hover { background-color: var(--neon-pink) !important; color: #ffffff !important; }
.form-input, .form-select, textarea.form-input { background: var(--neon-input) !important; border-color: var(--neon-border) !important; color: var(--neon-text) !important; border-radius: var(--neon-radius) !important; }
.form-input:focus, .form-select:focus { border-color: var(--neon-primary) !important; box-shadow: 0 0 0 0.1rem rgba(0, 229, 255, 0.35) !important; }
.form-checkbox input:checked + .form-icon, .form-radio input:checked + .form-icon, .form-switch input:checked + .form-icon { background: var(--neon-primary) !important; border-color: var(--neon-primary) !important; }
.form-label { color: var(--neon-text) !important; }
.slider-ctrl label, span.input-group-addon { color: var(--neon-text) !important; }
.input-group .input-group-addon { background: var(--neon-surface) !important; border-color: var(--neon-border) !important; color: var(--neon-text) !important; }
.tab-item { color: var(--neon-text) !important; }
.tab .tab-item a { color: var(--neon-text) !important; }
.tab .tab-item a.active, .tab .tab-item.active a { border-bottom-color: var(--neon-primary) !important; color: var(--neon-primary) !important; }
section .active, li .active { color: var(--neon-primary) !important; }
.menu { background: var(--neon-surface) !important; border: 1px solid var(--neon-border) !important; box-shadow: 0 0.2rem 0.8rem rgba(0, 0, 0, 0.6) !important; border-radius: var(--neon-radius) !important; }
.menu .menu-item { color: var(--neon-primary) !important; }
.menu .menu-item > .menu-entry:focus, .menu .menu-item > .menu-entry:hover, .menu .menu-item > a:focus, .menu .menu-item > a:hover { background: rgba(0, 229, 255, 0.12) !important; color: var(--neon-primary) !important; }
.menu .menu-item > .menu-entry:active, .menu .menu-item > .menu-entry.active, .menu .menu-item > a:active, .menu .menu-item > a.active { background: rgba(0, 229, 255, 0.12) !important; color: var(--neon-primary) !important; }
.menu .divider, .divider { border-top-color: var(--neon-border) !important; }
.panel .menu-item:active, .panel .menu-item.active { background: var(--neon-primary) !important; color: var(--neon-on-primary) !important; }
.modal .modal-overlay { background: rgba(2, 8, 12, 0.8) !important; opacity: 1 !important; }
.modal .modal-container { background: var(--neon-surface) !important; color: var(--neon-text) !important; border: 1px solid var(--neon-border) !important; border-radius: var(--neon-radius) !important; box-shadow: 0 0 24px rgba(0, 229, 255, 0.2) !important; }
.modal .modal-header, .modal .modal-title { color: var(--neon-primary) !important; }
.modal .modal-body, .modal .modal-footer { background: var(--neon-surface) !important; color: var(--neon-text) !important; }
.toast { background: rgba(22, 27, 34, 0.95) !important; border-color: var(--neon-border) !important; color: var(--neon-text) !important; }
.toast.toast-primary { background: rgba(0, 184, 204, 0.95) !important; border-color: var(--neon-primary) !important; color: #ffffff !important; }
.toast.toast-error { background: rgba(255, 46, 136, 0.95) !important; border-color: var(--neon-pink) !important; color: #ffffff !important; }
.label { background: var(--neon-input) !important; color: var(--neon-text) !important; }
.label.label-primary { background: var(--neon-primary) !important; color: var(--neon-on-primary) !important; }
.label.label-error { background: var(--neon-pink) !important; color: #ffffff !important; }
.badge[data-badge]::after, .badge:not([data-badge])::after { background: var(--neon-pink) !important; color: #ffffff !important; }
.bar { background: var(--neon-input) !important; }
.bar .bar-item { background: linear-gradient(90deg, var(--neon-primary-dark), var(--neon-primary)) !important; box-shadow: 0 0 8px rgba(0, 229, 255, 0.6) !important; color: var(--neon-on-primary) !important; }
.tooltip::after { background: rgba(0, 184, 204, 0.95) !important; color: #ffffff !important; }
.loading::after { border-color: var(--neon-primary) !important; border-right-color: transparent !important; border-top-color: transparent !important; }
.terminal { background: #04080c !important; color: var(--neon-terminal) !important; border-color: var(--neon-border) !important; }
.terminal .echo { color: var(--neon-primary) !important; }
.terminal .error { color: var(--neon-pink) !important; }
.files-list { background: var(--neon-input) !important; border-color: var(--neon-border) !important; }
.file-line:hover { color: var(--neon-primary) !important; background: rgba(0, 229, 255, 0.08) !important; }
.files-list-footer { color: var(--neon-primary) !important; }
.comment { background: rgba(0, 229, 255, 0.12) !important; color: var(--neon-primary) !important; }
.field-group { color: var(--neon-primary) !important; }
.control-fieldset { color: var(--neon-text) !important; }
.item-selection-list:hover { background: rgba(0, 229, 255, 0.12) !important; }
.items-list-top-separator legend { background: var(--neon-surface) !important; }
.empty { background: var(--neon-surface) !important; color: var(--neon-text) !important; }
.table th, .table td { border-bottom-color: var(--neon-border) !important; color: var(--neon-text) !important; }
.table.table-striped tbody tr:nth-of-type(odd) { background: var(--neon-input) !important; }
::-webkit-scrollbar { width: 0.35rem; height: 0.35rem; }
::-webkit-scrollbar-track { background: var(--neon-bg) !important; }
::-webkit-scrollbar-thumb { background: rgba(0, 229, 255, 0.35) !important; border-radius: 0.2rem !important; }
::-webkit-scrollbar-thumb:hover { background: var(--neon-primary) !important; }
